// Faithful reproduction of @visx/responsive's ParentSize component at the
// pinned pre-fix base. It renders a single wrapper div sized 100% x 100% that
// is BOTH the layout wrapper AND the element measured by the ResizeObserver in
// useParentSize. The measured dimensions are handed to the child render
// function.
const defaultParentSizeStyles = { width: "100%", height: "100%" };

export default function ParentSize({
  className,
  children,
  debounceTime,
  ignoreDimensions,
  initialSize,
  parentSizeStyles = defaultParentSizeStyles,
  enableDebounceLeadingCall = true,
  resizeObserverPolyfill,
  ...restProps
}) {
  const { parentRef, node, resize, ...dimensions } = useParentSize({
    initialSize,
    debounceTime,
    ignoreDimensions,
    enableDebounceLeadingCall,
    resizeObserverPolyfill,
  });

  return createElement(
    "div",
    { style: parentSizeStyles, ref: parentRef, className, ...restProps },
    children({ ...dimensions, ref: node, resize })
  );
}
