  ".html": "text/html",
  ".js": "application/javascript",
  ".mjs": "application/javascript",
  ".json": "application/json",
  ".css": "text/css",
};

function proxyScene(req, res) {
  if (!SERVICE) {
    res.writeHead(500);
    res.end("no scene service");
    return;
  }
  const suffix = req.url.slice("/scene".length) || "";
  const url = SERVICE.replace(/\/$/, "") + "/scene" + suffix;
  http
    .get(url, (up) => {
      res.writeHead(up.statusCode || 502, {
        "content-type": up.headers["content-type"] || "application/json",
      });
      up.pipe(res);
    })
    .on("error", (e) => {
      res.writeHead(502);
      res.end(String(e));
    });
}

